"""The rounding rules in meterbill.money."""

import unittest
from decimal import ROUND_DOWN, ROUND_HALF_EVEN, ROUND_HALF_UP, Decimal

from meterbill import money

D = Decimal


class RoundAmount(unittest.TestCase):
    def test_ties(self):
        self.assertEqual(money.round_amount(D("0.125"), money.CENT, money.HALF_UP), D("0.13"))
        self.assertEqual(money.round_amount(D("0.125"), money.CENT, money.HALF_EVEN), D("0.12"))
        self.assertEqual(money.round_amount(D("-0.135"), money.CENT, money.HALF_UP), D("-0.14"))
        self.assertEqual(money.round_amount(D("0.139"), money.CENT, money.DOWN), D("0.13"))

    def test_exponent_of_step(self):
        got = money.round_amount(D("7"), D("0.05"), money.HALF_UP)
        self.assertEqual(str(got), "7.00")
        self.assertEqual(str(money.round_amount(D("7.5"), D("1"), money.HALF_EVEN)), "8")

    def test_coarse_steps(self):
        self.assertEqual(money.round_amount(D("1.025"), D("0.05"), money.HALF_UP), D("1.05"))
        self.assertEqual(money.round_amount(D("1.025"), D("0.05"), money.HALF_EVEN), D("1.00"))

    def test_matches_quantize(self):
        modes = {money.HALF_UP: ROUND_HALF_UP, money.HALF_EVEN: ROUND_HALF_EVEN, money.DOWN: ROUND_DOWN}
        for text in ("0.005", "-0.005", "2.5", "1234567.8951", "-0.0001", "0"):
            for method, mode in modes.items():
                self.assertEqual(
                    str(money.round_amount(D(text), D("0.01"), method)),
                    str(D(text).quantize(D("0.01"), rounding=mode)),
                )

    def test_errors(self):
        with self.assertRaises(TypeError):
            money.round_amount(1.5, money.CENT, money.DOWN)
        with self.assertRaises(ValueError):
            money.round_amount(D("1"), money.CENT, "up")
        with self.assertRaises(ValueError):
            money.round_amount(D("1"), D("0"), money.DOWN)


class Allocate(unittest.TestCase):
    def test_parts_add_up(self):
        amounts = [D("5.3469"), D("7.8966")]
        parts = money.allocate(amounts, money.CENT)
        self.assertEqual(sum(parts), D("13.24"))
        self.assertEqual(parts, [D("5.34"), D("7.90")])

    def test_empty_and_input_kept(self):
        self.assertEqual(money.allocate([], money.CENT), [])
        amounts = [D("1.005")]
        money.allocate(amounts, money.CENT)
        self.assertEqual(amounts, [D("1.005")])


class Legacy(unittest.TestCase):
    def test_cents(self):
        self.assertEqual(money.legacy_cents(2.675), 2.68)
        self.assertEqual(money.legacy_cents(-4.25), -4.25)
        self.assertEqual(money.legacy_cents(1.23456, 4), 1.2346)
        self.assertEqual(money.legacy_cents(2.5, 0), 3.0)


class Fixed(unittest.TestCase):
    def test_float(self):
        self.assertEqual(money.fixed(0.125, 2), "0.12")
        self.assertEqual(money.fixed(2.5, 0), "2")
        with self.assertRaises(ValueError):
            money.fixed(0.125, 2, money.HALF_UP)

    def test_decimal(self):
        self.assertEqual(money.fixed(D("0.125"), 2, money.HALF_UP), "0.13")
        self.assertEqual(money.fixed(D("0.125"), 2), "0.12")
        self.assertEqual(money.fixed(D("1E+3"), 1), "1000.0")
        self.assertEqual(money.fixed(D("21.5"), 0, money.HALF_UP), "22")


if __name__ == "__main__":
    unittest.main()
